    termsDesc: "\u8D2D\u4E70\u5E76\u4F7F\u7528 GoPanel \u5373\u8868\u793A\u4F60\u5DF2\u9605\u8BFB\u5E76\u540C\u610F\u4EE5\u4E0B\u6761\u6B3E\u3002\u82E5\u4E0E\u6B63\u5F0F\u534F\u8BAE\u4E0D\u4E00\u81F4\uFF0C\u4EE5\u6B63\u5F0F\u534F\u8BAE\u4E3A\u51C6\u3002",
    effectiveDate: "\u751F\u6548\u65E5\u671F\uFF1A{date}",
    term1Title: "1. \u6388\u6743\u8303\u56F4",
    term1p1: "\u6388\u6743\u4EC5\u7528\u4E8E\u5408\u6CD5\u7528\u9014\u7684\u670D\u52A1\u5668\u7BA1\u7406\u4E0E\u8FD0\u7EF4\u573A\u666F\uFF0C\u4E0D\u5F97\u7528\u4E8E\u4EFB\u4F55\u8FDD\u53CD\u6CD5\u5F8B\u6CD5\u89C4\u6216\u4FB5\u5BB3\u4ED6\u4EBA\u6743\u76CA\u7684\u884C\u4E3A\u3002",
    term1p2: "\u6388\u6743\u7C7B\u578B\u4EE5\u4F60\u8D2D\u4E70\u7684\u5546\u54C1\u8BF4\u660E\u4E3A\u51C6\uFF08\u8BA2\u9605\u3001\u6C38\u4E45\u6388\u6743\u3001\u6216\u5176\u5B83\u6388\u6743\u5F62\u6001\uFF09\u3002",
    term2Title: "2. \u4F7F\u7528\u9650\u5236",
    term2p1: "\u7981\u6B62\u5BF9 GoPanel \u8FDB\u884C\u9006\u5411\u5DE5\u7A0B\u3001\u7834\u89E3\u3001\u7ED5\u8FC7\u6388\u6743\u6821\u9A8C\u3001\u4E8C\u6B21\u5206\u53D1\u6216\u552E\u5356\u6388\u6743\u51ED\u8BC1\u3002",
    term2p2: "\u7981\u6B62\u79FB\u9664\u6216\u7BE1\u6539\u4EA7\u54C1\u4E2D\u7684\u7248\u6743\u3001\u5546\u6807\u4E0E\u6743\u5229\u58F0\u660E\u3002",
    term3Title: "3. \u4EA4\u4ED8\u4E0E\u7ED1\u5B9A",
    term3p1: "\u652F\u4ED8\u6210\u529F\u540E\u7CFB\u7EDF\u4F1A\u81EA\u52A8\u53D1\u653E\u4EA4\u4ED8\u4FE1\u606F\uFF08\u5982\u6388\u6743\u7801\u3001\u4E0B\u8F7D\u5730\u5740\u3001\u4F7F\u7528\u8BF4\u660E\u7B49\uFF09\u3002",
    term3p2: "\u5982\u6388\u6743\u5B58\u5728\u7ED1\u5B9A\u89C4\u5219\uFF08\u8BBE\u5907/\u8282\u70B9\u6570/\u5230\u671F\u65F6\u95F4/\u529F\u80FD\u8303\u56F4\uFF09\uFF0C\u4EE5\u5546\u54C1\u9875\u9762\u6216\u4EA4\u4ED8\u8BF4\u660E\u4E3A\u51C6\u3002",
    term4Title: "4. \u9000\u6B3E\u4E0E\u98CE\u63A7",
    term4p1: "\u6570\u5B57\u5316\u5546\u54C1\u4E00\u7ECF\u4EA4\u4ED8\u53EF\u80FD\u65E0\u6CD5\u64A4\u56DE\uFF0C\u56E0\u6B64\u9000\u6B3E\u653F\u7B56\u4EE5\u5546\u54C1\u9875\u8BF4\u660E\u4E0E\u552E\u540E\u653F\u7B56\u4E3A\u51C6\u3002",
    term4p2: "\u82E5\u68C0\u6D4B\u5230\u5F02\u5E38\u4F7F\u7528\u3001\u5171\u4EAB/\u5012\u5356\u6388\u6743\u6216\u5176\u4ED6\u9AD8\u98CE\u9669\u884C\u4E3A\uFF0C\u5E73\u53F0\u6709\u6743\u6682\u505C\u670D\u52A1\u5E76\u4FDD\u7559\u8FFD\u8D23\u6743\u5229\u3002",
    term5Title: "5. \u514D\u8D23\u58F0\u660E",
    term5p1: "GoPanel \u6309\u201C\u73B0\u72B6\u201D\u63D0\u4F9B\u3002\u6211\u4EEC\u5C06\u6301\u7EED\u4F18\u5316\uFF0C\u4F46\u4E0D\u5BF9\u56E0\u4E0D\u53EF\u6297\u529B\u3001\u7B2C\u4E09\u65B9\u670D\u52A1\u6545\u969C\u3001\u914D\u7F6E\u9519\u8BEF\u7B49\u9020\u6210\u7684\u635F\u5931\u627F\u62C5\u8D23\u4EFB\u3002",
    term5p2: "\u4F60\u5E94\u81EA\u884C\u505A\u597D\u6570\u636E\u5907\u4EFD\u3001\u6743\u9650\u7BA1\u7406\u4E0E\u5B89\u5168\u52A0\u56FA\uFF0C\u5E76\u5BF9\u81EA\u8EAB\u4F7F\u7528\u884C\u4E3A\u8D1F\u8D23\u3002",
    contact: "\u82E5\u4F60\u9700\u8981\u4F01\u4E1A\u6388\u6743\u6761\u6B3E\u3001\u6279\u91CF\u91C7\u8D2D\u3001\u53D1\u7968\u6216\u5B9A\u5236\u529F\u80FD\uFF0C\u8BF7\u8054\u7CFB\u5546\u52A1\u652F\u6301\u3002\u82E5\u4F60\u5BF9\u6761\u6B3E\u6709\u7591\u95EE\uFF0C\u53EF\u63D0\u4EA4\u5DE5\u5355\u6216\u901A\u8FC7\u793E\u533A\u6E20\u9053\u54A8\u8BE2\u3002",
    faqTitle: "\u5E38\u89C1\u95EE\u9898",
    faqDesc: "\u4F18\u5148\u89E3\u7B54\u8D2D\u4E70\u540E\u6700\u5E38\u89C1\u7684\u67E5\u8BE2\u4E0E\u6388\u6743\u95EE\u9898\u3002",
    faq1Title: "\u67E5\u8BE2\u4E0D\u5230\u4EA4\u4ED8\u4FE1\u606F\u600E\u4E48\u529E\uFF1F",
    faq1p1: "1) \u8BF7\u786E\u8BA4\u8BA2\u5355\u5DF2\u652F\u4ED8\u6210\u529F\uFF1B\u672A\u652F\u4ED8\u8BA2\u5355\u4E0D\u4F1A\u663E\u793A\u4EA4\u4ED8\u4FE1\u606F\u3002",
    faq1p2: "2) \u8BF7\u5728\u4E0B\u5355\u65F6\u4F7F\u7528\u7684\u6D4F\u89C8\u5668\u4E2D\u67E5\u8BE2\uFF08\u7CFB\u7EDF\u4F1A\u6821\u9A8C\u6D4F\u89C8\u5668\u8BBF\u5BA2\u6807\u8BC6\uFF09\u3002",
    faq1p3: "3) \u82E5\u5DF2\u767B\u5F55\uFF0C\u8BF7\u8FDB\u5165\u7528\u6237\u4E2D\u5FC3\u67E5\u770B\u8BA2\u5355\u8BE6\u60C5\u3002",
    faq2Title: "\u6388\u6743\u7801\u53EF\u4EE5\u591A\u4EBA\u5171\u4EAB\u5417\uFF1F",
    faq2p1: "\u4E0D\u53EF\u4EE5\u3002\u6388\u6743\u4EC5\u9650\u8D2D\u4E70\u65B9\u5728\u8BB8\u53EF\u8303\u56F4\u5185\u4F7F\u7528\u3002\u5171\u4EAB\u3001\u5012\u5356\u6216\u516C\u5F00\u4F20\u64AD\u6388\u6743\u7801\u5C06\u89E6\u53D1\u98CE\u63A7\u5904\u7406\u3002",
    metaTitle: "\u6388\u6743\u8BB8\u53EF\u534F\u8BAE - GoPanel",
