    lg1Title: "\u4FEE\u6539\u521D\u59CB\u5BC6\u7801",
    lg1Desc: "\u9996\u6B21\u767B\u5F55\u540E\u7ACB\u5373\u4FEE\u6539\u7BA1\u7406\u5458\u5BC6\u7801\uFF0C\u5E76\u786E\u4FDD\u4F7F\u7528\u5F3A\u5BC6\u7801\uFF08\u957F\u5EA6\u3001\u590D\u6742\u5EA6\u3001\u552F\u4E00\u6027\uFF09\u3002",
    lg2Title: "\u5F00\u542F HTTPS",
    lg2Desc: "\u63A8\u8350\u4E3A\u9762\u677F\u5165\u53E3\u7ED1\u5B9A\u57DF\u540D\u5E76\u5F00\u542F HTTPS\uFF0C\u907F\u514D\u660E\u6587\u767B\u5F55\u4E0E\u4F1A\u8BDD\u52AB\u6301\u98CE\u9669\u3002",
    lg3Title: "\u6700\u5C0F\u6743\u9650\u534F\u4F5C",
    lg3Desc: "\u56E2\u961F\u591A\u4EBA\u4F7F\u7528\u65F6\uFF0C\u4E3A\u6BCF\u4F4D\u6210\u5458\u521B\u5EFA\u72EC\u7ACB\u8D26\u53F7\u5E76\u5206\u914D\u6700\u5C0F\u6743\u9650\uFF0C\u907F\u514D\u5171\u4EAB\u7BA1\u7406\u5458\u8D26\u53F7\u3002",
    lg4Title: "\u914D\u7F6E\u5907\u4EFD\u7B56\u7565",
    lg4Desc: "\u5BF9\u5173\u952E\u914D\u7F6E\u4E0E\u6570\u636E\u5E93\u5EFA\u7ACB\u5B9A\u671F\u5907\u4EFD\u4E0E\u4FDD\u7559\u7B56\u7565\uFF0C\u91CD\u5927\u53D8\u66F4\u524D\u624B\u52A8\u505A\u4E00\u6B21\u5FEB\u7167\u3002",
    commonTitle: "\u5E38\u7528\u529F\u80FD\uFF08\u600E\u4E48\u7528\u66F4\u987A\uFF09",
    commonDesc: "\u4E0B\u5217\u662F\u6700\u5178\u578B\u7684\u4F7F\u7528\u8DEF\u5F84\uFF0C\u9002\u5408\u7B2C\u4E00\u6B21\u4E0A\u624B\u6309\u6B65\u9AA4\u7167\u505A\u3002",
    cm1Title: "\u7F51\u7AD9\u4E0E\u57DF\u540D\uFF1A\u4ECE 0 \u5230\u4E0A\u7EBF",
    cm1p1: "1) \u6DFB\u52A0\u7AD9\u70B9\uFF1A\u9009\u62E9\u57DF\u540D\u4E0E\u7AD9\u70B9\u76EE\u5F55\u6216\u5E94\u7528\u90E8\u7F72\u65B9\u5F0F\u3002",
    cm1p2: "2) \u914D\u7F6E\u53CD\u5411\u4EE3\u7406\uFF1A\u5C06\u57DF\u540D\u6307\u5411\u4F60\u7684\u5E94\u7528\u7AEF\u53E3\u6216\u5BB9\u5668\u670D\u52A1\u3002",
    cm1p3: "3) \u5F00\u542F HTTPS\uFF1A\u7533\u8BF7\u8BC1\u4E66\u5E76\u914D\u7F6E\u81EA\u52A8\u7EED\u671F\u3002",
    cm1p4: "4) \u9A8C\u8BC1\u4E0A\u7EBF\uFF1A\u68C0\u67E5 DNS\u3001\u7AEF\u53E3\u3001\u8BC1\u4E66\u94FE\u4E0E\u8BBF\u95EE\u65E5\u5FD7\u3002",
    cm2Title: "SSL \u8BC1\u4E66\uFF1A\u7533\u8BF7\u4E0E\u81EA\u52A8\u7EED\u7B7E",
    cm2p1: "\u786E\u4FDD\u8BC1\u4E66\u7533\u8BF7\u524D\u57DF\u540D\u89E3\u6790\u5DF2\u751F\u6548\uFF0C\u4E14\u9A8C\u8BC1\u65B9\u5F0F\uFF08HTTP/DNS\uFF09\u53EF\u901A\u8FC7\u3002",
    cm2p2: "\u5EFA\u8BAE\uFF1A\u4E3A\u5173\u952E\u4E1A\u52A1\u57DF\u540D\u542F\u7528\u81EA\u52A8\u7EED\u7B7E\uFF0C\u5E76\u5173\u6CE8\u7EED\u7B7E\u5931\u8D25\u901A\u77E5\u3002",
    cm3Title: "\u5BB9\u5668\u4E0E\u5E94\u7528\uFF1A\u5FEB\u901F\u90E8\u7F72\u5E38\u7528\u670D\u52A1",
    cm3p1: "\u4F18\u5148\u4F7F\u7528\u201C\u5E94\u7528\u5546\u5E97/\u6A21\u677F\u201D\u90E8\u7F72\u6570\u636E\u5E93\u3001\u7F13\u5B58\u3001\u6D88\u606F\u961F\u5217\u7B49\u5E38\u89C1\u7EC4\u4EF6\u3002",
    cm3p2: "\u90E8\u7F72\u540E\u68C0\u67E5\uFF1A\u7AEF\u53E3\u6620\u5C04\u3001\u6570\u636E\u5377\u6302\u8F7D\u3001\u73AF\u5883\u53D8\u91CF\u3001\u5065\u5EB7\u68C0\u67E5\u4E0E\u65E5\u5FD7\u3002",
    cm4Title: "\u6570\u636E\u5E93\uFF1A\u521B\u5EFA\u3001\u6388\u6743\u4E0E\u5907\u4EFD",
    cm4p1: "\u751F\u4EA7\u73AF\u5883\u5EFA\u8BAE\uFF1A\u5355\u72EC\u8D26\u53F7\u3001\u6700\u5C0F\u6743\u9650\u3001\u5B9A\u671F\u5907\u4EFD\u3001\u53EF\u7528\u6027\u76D1\u63A7\u3002",
    cm4p2: "\u53D8\u66F4\u5EFA\u8BAE\uFF1A\u5148\u5907\u4EFD\u518D\u6539\u7ED3\u6784\uFF0C\u5173\u952E\u64CD\u4F5C\u7559\u5B58\u5BA1\u8BA1\u8BB0\u5F55\u3002",
    cm5Title: "\u6D41\u6C34\u7EBF\uFF08CI/CD\uFF09\uFF1A\u628A\u53D1\u5E03\u6D41\u7A0B\u56FA\u5316\u4E0B\u6765",
